<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\StorePurchaseRequisitionRequest; use App\Models\{Product,PurchaseRequisition}; use App\Services\PurchaseManagementService; use Illuminate\Http\{RedirectResponse,Request}; use Inertia\{Inertia,Response};
class PurchaseRequisitionController extends Controller { public function __construct(protected PurchaseManagementService $service){} public function index(Request $r):Response{return Inertia::render('Admin/PurchaseRequisitions/Index',['requisitions'=>PurchaseRequisition::with('requester:id,name','approver:id,name')->latest()->paginate(15)]);} public function create():Response{return Inertia::render('Admin/PurchaseRequisitions/Create',['products'=>Product::where('status',true)->orderBy('name')->get(['id','name','sku','purchase_price']),'suggestedNumber'=>'PR-'.now()->format('Ymd-His')]);} public function store(StorePurchaseRequisitionRequest $r):RedirectResponse{$x=$this->service->createRequisition($r->validated(),$r->user()->id);return redirect()->route('admin.purchase-requisitions.show',$x)->with('success','Purchase requisition submitted.');} public function show(PurchaseRequisition $purchaseRequisition):Response{return Inertia::render('Admin/PurchaseRequisitions/Show',['requisition'=>$purchaseRequisition->load('items.product','requester:id,name','approver:id,name')]);} public function approve(Request $r,PurchaseRequisition $purchaseRequisition):RedirectResponse{$r->user()->can('purchase-requisitions.approve')||abort(403);$this->service->approveRequisition($purchaseRequisition,$r->user()->id);return back()->with('success','Requisition approved.');}}
